      expect(json['params']['model'], 'gpt-4');
    });

    test('parses JSON-array override values', () {
      final json =
          jsonDecode(_run(['run', 'teammate', '--list', '[1,2]'])) as Map;
      expect(json['params']['list'], [1, 2]);
    });

